pub fn run() -> Vec<String> {
    let mut lines = vec![
        String::from("alpha"),
        String::from("[section]"),
        String::from("beta"),
    ];

    for line in &lines {
        if line.starts_with('[') {
            lines.push(String::from("-- marker --"));
        }
    }

    lines
}

exercises.tests:
#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn appends_one_marker() {
        assert_eq!(
            run(),
            vec![
                String::from("alpha"),
                String::from("[section]"),
                String::from("beta"),
                String::from("-- marker --"),
            ]
        );
    }
}

exercises.solution:
pub fn run() -> Vec<String> {
    let mut lines = vec![
        String::from("alpha"),
        String::from("[section]"),
        String::from("beta"),
    ];

    let mut extra = Vec::new();
    for line in &lines {
        if line.starts_with('[') {
            extra.push(String::from("-- marker --"));
        }
    }
    lines.extend(extra);

    lines
}

